H.background();
const w = H.W, h = H.H;
const rho = Math.max(100, P.rho), A = Math.max(0.01, P.area), m = Math.max(0.1, P.mass);
const g = 9.8;
const F = m * g;
const Pr = F / A;
const cx = w * 0.42, baseY = h * 0.78;
const bw = H.clamp(40 + 120 * Math.sqrt(A), 50, 240);
const bh = H.clamp(60 + 0.04 * m, 50, 150);
H.line(40, baseY, w - 40, baseY, { color: H.colors.axis, width: 2 });
const settle = 4 * Math.abs(Math.sin(t * 1.4)) * Math.exp(-((t % 4)) * 0.5);
const by = baseY - bh - settle;
H.rect(cx - bw / 2, by, bw, bh, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 4 });
H.text("m = " + m.toFixed(1) + " kg", cx - bw / 2 + 6, by + bh / 2, { color: H.colors.ink, size: 13 });
H.arrow(cx, by + bh, cx, by + bh + 46, { color: H.colors.warn, width: 3 });
H.text("F = mg", cx + 8, by + bh + 30, { color: H.colors.warn, size: 13 });
// pressure reaction arrows: length scales with the actual pressure P = F/A,
// so MORE mass -> taller arrows, and the SAME weight over a BIGGER area A
// (which also widens the block) -> shorter arrows.  log keeps the range sane.
const pLen = H.clamp(6 * Math.log10(Pr + 1), 6, 60);
const np = 5;
for (let i = 0; i < np; i++) {
  const px = cx - bw / 2 + bw * (i + 0.5) / np;
  const amp = pLen + 4 * Math.sin(t * 3 - i * 0.6);
  H.arrow(px, baseY, px, baseY - amp, { color: H.colors.good, width: 2, head: 7 });
}
H.text("pressure on area A", cx - bw / 2, baseY + 18, { color: H.colors.good, size: 12 });
H.text("Density & Pressure", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("P = F / A,   F = m g", 24, 52, { color: H.colors.sub, size: 13 });
H.text("F = " + F.toFixed(1) + " N    A = " + A.toFixed(2) + " m2", 24, 74, { color: H.colors.sub, size: 13 });
H.text("P = " + Pr.toFixed(0) + " Pa", 24, 96, { color: H.colors.accent, size: 15, weight: 700 });
H.text("density rho = " + rho.toFixed(0) + " kg/m3", 24, 118, { color: H.colors.sub, size: 13 });
H.legend([{ label: "weight F=mg", color: H.colors.warn }, { label: "pressure F/A", color: H.colors.good }], w - 175, 28);
